/bin/bash -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
const manifest = JSON.parse(fs.readFileSync('.next/prerender-manifest.json', 'utf8'));
const news = manifest.routes['/news'];
const preview = manifest.routes['/preview'];
assert.equal(news.initialRevalidateSeconds, 3600);
assert.equal(preview.renderingMode, 'PARTIALLY_STATIC');
const shell = fs.readFileSync('.next/server/app/preview.html', 'utf8');
assert.ok(shell.includes('Editor preview'));
assert.ok(shell.includes('Loading preview'));
assert.ok("'!shell.includes('"'Untitled draft'));
console.log('Production artifacts verified: newsroom revalidates after 3600 seconds; preview shell contains a loading fallback without draft content.');
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
const base = 'http://127.0.0.1:3100';
for (const [path, expected] of [['/', 'Northstar Publishing'], ['/news', 'City council approves new park']]) {
  const response = await fetch(base + path);
  assert.equal(response.status, 200);
  assert.ok((await response.text()).includes(expected));
  if (path === '/news') assert.match(response.headers.get('cache-control'), /s-maxage=3600\\b/);
  console.log("'`PASS ${path}: HTTP 200 and expected content`);
}
const titles = ['"'Editor-A-draft', 'Editor-B-draft'];
await Promise.all(titles.map(async (title) => {
  const response = await fetch(base + '/preview', { headers: { Cookie: "'`draft-title=${title}` } });
  assert.equal(response.status, 200);
  assert.match(response.headers.get('"'cache-control'), /private/);
  assert.match(response.headers.get('cache-control'), /no-store/);
  const html = await response.text();
  assert.ok(html.includes("'`<p>${title}</p>`));
  for (const other of titles.filter((value) => value !== title)) assert.ok(!html.includes(other));
  console.log(`PASS /preview: isolated ${title}, private/no-store response`);
}));
const anonymous = await fetch(base + '"'/preview');
assert.equal(anonymous.status, 200);
const html = await anonymous.text();
assert.ok(html.includes('<p>Untitled draft</p>'));
for (const title of titles) assert.ok("'!html.includes(title));
console.log('"'PASS /preview without a cookie: Untitled draft, no content from prior editor requests');
NODE"
